def solution(data):
    df_sales = data.get('So_chi_tiet_ban_hang')
    if df_sales is None:
        raise DataNotFoundError("Không tìm thấy bảng bán hàng")

    cols = df_sales.columns.tolist()
    d_c = next((c for c in cols if any(k in str(c).lower() for k in ['ngày', 'date', 'thời gian'])), None)
    amt_col = next((c for c in cols if any(k in str(c).lower() for k in ['thành tiền', 'tổng tiền', 'tiền bán', 'doanh thu', 'tiền']) and 'thuế' not in str(c).lower()), None)
    if d_c and amt_col:
        df_sales['clean_date'] = clean_date(df_sales[d_c])
        mask = (df_sales['clean_date'].dt.year == 2026) & (df_sales['clean_date'].dt.month == 7) & (df_sales['clean_date'].dt.day >= 29) & (df_sales['clean_date'].dt.day <= 2)
        return int(round(clean_num(df_sales[amt_col][mask]).sum()))
    else:
        raise DataNotFoundError("Không tìm thấy cột ngày hoặc cột thành tiền trong bảng bán hàng")
